#include "integer_controller.hpp"
#include <QFile>
#include <QFileInfo>
#include <QSaveFile>
#include <cmath>
namespace tora::desktop {
IntegerController::IntegerController(ApplicationShell& shell):QObject(&shell),shell_(shell),input_(&shell){setObjectName("integer-controller");input_.setObjectName("integer-lp-input-controller");input_.setParent(this);connect(&input_,&LpInputController::changed,this,[this]{if(installing_)return;if(input_.document())document_.integral.resize(input_.document()->problem.variables.size(),true);session_.reset();result_.reset();emit changed();emit resultChanged();});}
void IntegerController::fail(const QString& message){dialogs().showError("Integer programming",message);}
std::string IntegerController::encode()const{if(!input_.document())throw std::invalid_argument("Initialize an Integer model first");auto next=document_;next.lp=*input_.document();return next.encode();}
bool IntegerController::dirty()const{if(!input_.document())return false;try{return encode()!=checkpoint_;}catch(const std::exception&){return true;}}
bool IntegerController::commit(){return input_.commitPendingInput();}
void IntegerController::install(compat::IntegerDocument doc,QString path,bool ro,bool saved){installing_=true;input_.setEditingEnabled(!ro);input_.loadDocument(doc.lp);document_=std::move(doc);installing_=false;path_=std::move(path);readOnly_=ro;checkpoint_=saved?encode():std::string{};session_.reset();result_.reset();undo_.reset();selectedColumn_=-1;clipboardFlag_.reset();emit changed();emit resultChanged();emit modelReplaced();}
bool IntegerController::initialize(const QString& title,int n,int m){if(n<1 || n>100 || m<1 || m>100){fail("Enter 1..100 variables and constraints");return false;}if(!allowLeave())return false;auto p=lp::LpProblem::blank(static_cast<std::size_t>(n),static_cast<std::size_t>(m));install(compat::IntegerDocument::create(compat::ToraLpCodec::create(p),std::vector<bool>(static_cast<std::size_t>(n),true)));return input_.setTitle(title);}
bool IntegerController::loadExample(){if(!allowLeave())return false;auto p=lp::LpProblem::blank(2,2);p.title="Integer branch-and-bound example";p.objective={3,2};p.constraints={{{2,1},lp::Relation::LessEqual,4.5},{{1,2},lp::Relation::LessEqual,4.5}};install(compat::IntegerDocument::create(compat::ToraLpCodec::create(p),{true,true}));return true;}
bool IntegerController::setFlag(int index,bool value){if(readOnly_ || index<0 || index>=static_cast<int>(document_.integral.size()))return false;if(document_.integral[static_cast<std::size_t>(index)]==value)return true;document_.integral[static_cast<std::size_t>(index)]=value;session_.reset();result_.reset();emit changed();emit resultChanged();return true;}
bool IntegerController::setFormat(core::NumberFormat format){if(readOnly_ || !input_.document())return false;try{(void)core::NumberFormatter(format);auto doc=*input_.document();doc.inputFormat=format;return input_.loadDocument(std::move(doc));}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));return false;}}
bool IntegerController::openFile(const QString& path,bool ro){try{QFile file(path);if(!file.open(QIODevice::ReadOnly) || file.size()>qint64(compat::ToraLpCodec::MaxFileBytes))throw std::invalid_argument("Cannot open Integer file or file exceeds 4 MiB");const auto bytes=file.readAll();auto doc=compat::IntegerDocument::decode(std::string_view(bytes.constData(),static_cast<std::size_t>(bytes.size())));if(!allowLeave())return false;install(std::move(doc),path,ro,true);return true;}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));return false;}}
bool IntegerController::saveTo(const QString& path){if(!input_.document() || !commit())return false;try{const auto identity=[](const QString& p){QFileInfo f(p);return f.exists()?f.canonicalFilePath():f.absoluteFilePath();};if(readOnly_ && identity(path)==identity(path_))throw std::invalid_argument("Read-only input: choose a different filename");const auto bytes=QByteArray::fromStdString(encode());QSaveFile file(path);if(!file.open(QIODevice::WriteOnly) || file.write(bytes)!=bytes.size() || !file.commit())throw std::runtime_error("Cannot complete Integer save");path_=path;readOnly_=false;input_.setEditingEnabled(true);checkpoint_=encode();emit changed();return true;}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));return false;}}
compat::IntegerDocument IntegerController::snapshot()const{auto doc=document_;doc.lp=*input_.document();return doc;}
void IntegerController::selectRow(int row){selectedColumn_=-1;input_.selectRow(row);}
void IntegerController::selectColumn(int column){selectedColumn_=column-1;input_.selectColumn(column);}
void IntegerController::clearSelection(){selectedColumn_=-1;input_.clearSelection();}
bool IntegerController::copySelection(){if(!input_.copySelection())return false;clipboardFlag_=selectedColumn_>=0 && selectedColumn_<static_cast<int>(flags().size())?std::optional<bool>(flags()[static_cast<std::size_t>(selectedColumn_)]):std::optional<bool>{};return true;}
bool IntegerController::pasteSelection(){if(readOnly_ || !input_.document())return false;auto before=snapshot();const int col=selectedColumn_;if(!input_.pasteSelection())return false;if(col>=0 && clipboardFlag_)document_.integral[static_cast<std::size_t>(col)]=*clipboardFlag_;undo_=std::move(before);emit changed();return true;}
bool IntegerController::deleteSelection(){if(readOnly_ || !input_.document())return false;auto before=snapshot();const int col=selectedColumn_;if(!input_.deleteSelection())return false;if(col>=0){auto flags=before.integral;flags.erase(flags.begin()+col);document_.integral=std::move(flags);}undo_=std::move(before);selectedColumn_=-1;emit changed();emit modelReplaced();return true;}
bool IntegerController::insertSelection(bool beforeSelection){if(readOnly_ || !input_.document())return false;auto before=snapshot();const int col=selectedColumn_;if(!input_.insertSelection(beforeSelection))return false;if(col>=0){auto flags=before.integral;flags.insert(flags.begin()+col+(beforeSelection?0:1),true);document_.integral=std::move(flags);}undo_=std::move(before);selectedColumn_=-1;emit changed();emit modelReplaced();return true;}
bool IntegerController::undo(){if(readOnly_ || !undo_)return false;auto previous=std::move(*undo_);undo_.reset();installing_=true;input_.loadDocument(previous.lp);document_=std::move(previous);installing_=false;session_.reset();result_.reset();emit changed();emit resultChanged();emit modelReplaced();return true;}
bool IntegerController::requestOpen(){const auto choice=dialogs().chooseOpen();return choice && openFile(choice->path,choice->readOnly);}
bool IntegerController::requestSave(){if(!commit())return false;const auto path=dialogs().chooseSave(path_);return path && saveTo(*path);}
bool IntegerController::allowLeave(){if(!input_.document())return true;if(!commit())return false;if(!dirty())return true;const auto answer=dialogs().askSave();return answer==SaveChoice::No || (answer==SaveChoice::Yes && requestSave());}
bool IntegerController::solve(std::size_t limit){if(!input_.validateForSolve())return false;try{session_.reset();result_=integer::solve({input_.document()->problem,document_.integral},limit);emit resultChanged();return shell_.navigate("integer/result");}catch(const std::exception& e){session_.reset();result_.reset();emit resultChanged();fail(QString::fromUtf8(e.what()));return false;}}
bool IntegerController::startGuided(std::size_t limit){if(!input_.validateForSolve())return false;try{session_.emplace(integer::Problem{input_.document()->problem,document_.integral},limit);session_->next();result_=session_->result();emit resultChanged();return shell_.navigate("integer/result");}catch(const std::exception& e){session_.reset();result_.reset();emit resultChanged();fail(QString::fromUtf8(e.what()));return false;}}
bool IntegerController::nextGuided(std::optional<std::size_t> index){if(!session_)return false;try{session_->next(index);result_=session_->result();emit resultChanged();return true;}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));return false;}}
bool IntegerController::branchGuided(std::size_t variable){if(!session_)return false;try{session_->branch(variable);result_=session_->result();emit resultChanged();return true;}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));return false;}}
bool IntegerController::finishGuided(){if(!session_)return false;try{while(!session_->finished()){if(const auto index=session_->awaitingBranch()){const auto& x=session_->result().nodes[*index].values;std::size_t j=0;while(j<x.size() && (!flags()[j] || std::abs(x[j]-std::round(x[j]))<=1e-8))++j;session_->branch(j);}else session_->next();}result_=session_->result();emit resultChanged();return true;}catch(const std::exception& e){fail(QString::fromUtf8(e.what()));return false;}}
void IntegerController::setBoundPruning(bool enabled){if(session_)session_->setBoundPruning(enabled);}
IntegerController& integerController(ApplicationShell& shell){if(auto* c=shell.findChild<IntegerController*>("integer-controller"))return *c;return *new IntegerController(shell);}
}
